'use client';
import { useForm, useFieldArray } from 'react-hook-form';

export function {{form_name}}() {
  const { register, control, handleSubmit } = useForm({ defaultValues: { {{field_name}}: [{ value: '' }] } });
  const { fields, append, remove } = useFieldArray({ control, name: '{{field_name}}' });
  return (
    <form onSubmit={handleSubmit(d => console.log(d))}>
      {fields.map((f, i) => (
        <div key={f.id}>
          <input {...register(`{{field_name}}.${i}.value` as const)} />
          <button type="button" onClick={() => remove(i)}>x</button>
        </div>
      ))}
      <button type="button" onClick={() => append({ value: '' })}>+ 新增</button>
      <button>送出</button>
    </form>
  );
}
